"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def searchRotatedArray(arr, target):
    low = 0
    high = (len(arr) - 1)
    while (low <= high):
        mid = ((low + high) // 2)
        if (arr[mid] == target):
            return mid
            # Check if left half is sorted
        if (arr[low] <= arr[mid]):
            if ((arr[low] <= target) and (target <= arr[mid])):
                high = (mid - 1)
            else:
                low = (mid + 1)
                # Right half must be sorted
        else:
            if ((arr[mid] <= target) and (target <= arr[high])):
                low = (mid + 1)
            else:
                high = (mid - 1)
    return (-1)
